using namespace ark;using V=arkjson::Value;
static void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
static V parse(const char* text){V result;check(arkjson::parse(text,result),"test JSON");return result;}
static V write(AgentSession& session,const char* commands){V args=V::makeObj();args.set("expected_revision",V::makeNum((double)session.revision));args.set("commands",parse(commands));return session.call("doc_apply",args);}
static void apply(AgentSession& session,const char* commands){auto result=write(session,commands);if(result.find("isError")->b)throw std::runtime_error(result.find("structuredContent")->dump());}
static V report(AgentSession& session,u64 id){V args=V::makeObj();args.set("id",V::makeNum((double)id));auto result=session.call("native_inspect",args);if(result.find("isError")->b)throw std::runtime_error(result.dump());return *result.find("structuredContent")->find("report");}
static void rejected(AgentSession& session,const char* commands,const char* cause){const auto before=documentToJson(session.document,false,false);const auto revision=session.revision;auto result=write(session,commands);check(result.find("isError")->b,"invalid bounds must reject");if(result.dump().find(cause)==std::string::npos)throw std::runtime_error(std::string("Expected predicate ")+cause+" / "+result.dump());check(session.revision==revision&&documentToJson(session.document,false,false)==before,"invalid bounds publish no document or revision");}
