    const auto saved=documentToJson(session.document,false,false);Document restored;std::string error;check(parse(saved.c_str()).find("version")->num==36,"extended extrusion selects geometry-driven document version 36");check(documentFromJson(saved,restored,&error),"symmetric source roundtrip load");restored.recompute();check(restored.find(1)->get("depth")=="Depth"&&std::abs(resolveGeometryReference(restored,1,"cap.end").frame.m[13]-15)<1e-8,"persisted symmetric program recomputes exact caps");V downgraded=parse(saved.c_str());downgraded.set("version",V::makeNum(35));check(!documentFromJson(downgraded.dump(),restored,&error)&&error.find("version 36")!=std::string::npos,"downgraded extrusion source explicitly rejects instead of silently changing geometry");
