    info=face.call("doc_info",V::makeObj());outputs=0;for(const auto& feature:info.find("structuredContent")->find("features")->arr)outputs+=feature.find("output")->b;check(outputs==2,"separate face extrusion retains the source body as a physical output");
    apply(face,R"([{"op":"feature.edit","id":1,"p":{"density":"1"}},{"op":"feature.edit","id":2,"p":{"density":"1"}}])");auto physical=face.call("physics_inspect",V::makeObj());check(!physical.find("isError")->b&&physical.find("structuredContent")->find("mass_checked")->b&&std::abs(physical.find("structuredContent")->find("mass_g")->num-1.44)<1e-8,"aggregate physical mass retains both separately authored source and extrusion bodies");
    check(std::abs(resolveGeometryReference(face.document,2,"cap.start").frame.m[14]-10)<1e-8&&std::abs(resolveGeometryReference(face.document,2,"cap.end").frame.m[14])<1e-8,"face extrusion honors reversed symmetric total span");
    rejected(face,R"([{"op":"feature.add","type":"native_solid","p":{"op":"cylinder","radius":"10","height":"20"}},{"op":"feature.add","type":"native_solid","inputs":[3],"native":{"op":"extrude","source_face":"side"},"p":{"depth":"10"}}])","planar");
    AgentSession perforated;perforated.suppressFailureCapture();perforated.suppressIterationHistory();
